  const fs = require('fs');
  const path = require('path');

  // Function to recursively find all symbolic links
  function findSymlinks(dir, baseDir = dir) {
    const symlinks = [];

    try {
      const entries = fs.readdirSync(dir, { withFileTypes: true });

      for (const entry of entries) {
        const fullPath = path.join(dir, entry.name);

        if (entry.isSymbolicLink()) {
          symlinks.push(fullPath);
        } else if (entry.isDirectory()) {
          // Recursively search subdirectories
          try {
            symlinks.push(...findSymlinks(fullPath, baseDir));
          } catch (err) {
            // Skip directories we can't read
          }
        }
      }
    } catch (err) {
      // Skip if we can't read the directory
    }

    return symlinks;
  }

  // Function to check if a symlink is broken
  function isBrokenSymlink(symlinkPath) {
    try {
      // Try to stat the target (follows symlinks)
      fs.statSync(symlinkPath);
      return false; // Target exists
    } catch (err) {
      // If we get ENOENT, the symlink is broken
      return err.code === 'ENOENT';
    }
  }

  // Find all symlinks
  const allSymlinks = findSymlinks('/workspace');

  // Filter for broken symlinks
  const brokenLinks = allSymlinks.filter(isBrokenSymlink);

  // Sort for consistent output
  brokenLinks.sort();

  // Create the output content
  const content = brokenLinks.join('\n') + (brokenLinks.length > 0 ? '\n' : '');

  // Write to file
  fs.writeFileSync('/workspace/broken_links.txt', content);

  return {
    totalSymlinks: allSymlinks.length,
    brokenSymlinks: brokenLinks.length,
    brokenLinks: brokenLinks
  };
}

